system_maintenance.template:
# Check Service Status
# Generated: $(Get-Date)

$ServiceName = "{{servicename}}"

try {
    $Service = Get-Service -Name $ServiceName -ErrorAction Stop

    Write-Host "Service Name: $($Service.Name)" -ForegroundColor Cyan
    Write-Host "Display Name: $($Service.DisplayName)" -ForegroundColor Cyan
    Write-Host "Status: $($Service.Status)" -ForegroundColor $(if($Service.Status -eq 'Running'){'Green'}else{'Yellow'})
    Write-Host "Start Type: $($Service.StartType)" -ForegroundColor Cyan
}
catch {
    Write-Host "Service '$ServiceName' not found" -ForegroundColor Red
}

# Restart Scanner/WIA Service
# Generated: $(Get-Date)
# NOTE: This script requires Administrator privileges

Write-Host "=== RESTART SCANNER/WIA SERVICE ===" -ForegroundColor Cyan
Write-Host ""

# Check if running as administrator
$IsAdmin = ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

if (-not $IsAdmin) {
    Write-Host "[!] WARNING: This script is not running as Administrator" -ForegroundColor Red
    Write-Host "    This operation requires admin privileges to work properly" -ForegroundColor Yellow
    Write-Host ""
}

try {
    # Stop Windows Image Acquisition service
    Write-Host "Stopping Windows Image Acquisition (WIA) service..." -ForegroundColor Yellow
    Stop-Service -Name stisvc -Force -ErrorAction Stop
    Write-Host "  [OK] WIA service stopped" -ForegroundColor Green
    Write-Host ""

    # Kill common scanner processes if stuck
    Write-Host "Checking for stuck scanner processes..." -ForegroundColor Yellow
    $ScannerProcesses = Get-Process | Where-Object {
        $_.Name -match "scan|avision|wia|twain"
    }

    if ($ScannerProcesses) {
        $ProcessCount = ($ScannerProcesses | Measure-Object).Count
        Write-Host "  Found $ProcessCount scanner-related process(es)" -ForegroundColor Cyan

        foreach ($Process in $ScannerProcesses) {
            Write-Host "  Stopping: $($Process.Name) (PID: $($Process.Id))" -ForegroundColor Gray
        }

        $ScannerProcesses | Stop-Process -Force -ErrorAction SilentlyContinue
        Write-Host "  [OK] Scanner processes terminated" -ForegroundColor Green
    } else {
        Write-Host "  No stuck scanner processes found" -ForegroundColor Gray
    }
    Write-Host ""

    # Start WIA service again
    Write-Host "Starting Windows Image Acquisition (WIA) service..." -ForegroundColor Yellow
    Start-Service -Name stisvc -ErrorAction Stop
    Write-Host "  [OK] WIA service started" -ForegroundColor Green
    Write-Host ""

    # Verify service is running
    $ServiceStatus = (Get-Service -Name stisvc).Status
    if ($ServiceStatus -eq 'Running') {
        Write-Host "✅ SUCCESS: Scanner service restarted successfully!" -ForegroundColor Green
        Write-Host "Service Status: $ServiceStatus" -ForegroundColor Cyan
    } else {
        Write-Host "[WARNING] Service status: $ServiceStatus" -ForegroundColor Yellow
    }
}
catch {
    Write-Host "[ERROR] Failed to restart scanner service: $_" -ForegroundColor Red
    Write-Host "Make sure you are running PowerShell as Administrator" -ForegroundColor Yellow
}

# Repair Windows Image - DISM + SFC
# Generated: $(Get-Date)
# NOTE: This script requires Administrator privileges and internet connection

Write-Host "=== REPAIR WINDOWS IMAGE ===" -ForegroundColor Cyan
Write-Host ""

# Check if running as administrator
$IsAdmin = ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

if (-not $IsAdmin) {
    Write-Host "[ERROR] This script must run as Administrator" -ForegroundColor Red
    Write-Host "Please run PowerShell as Administrator and try again" -ForegroundColor Yellow
    exit 1
}

Write-Host "This process will:" -ForegroundColor Yellow
Write-Host "  1. Run DISM to repair the Windows image" -ForegroundColor Gray
Write-Host "  2. Run SFC to fix system files using the repaired image" -ForegroundColor Gray
Write-Host "  This may take 15-30 minutes..." -ForegroundColor Gray
Write-Host ""

# Step 1: DISM RestoreHealth
Write-Host "[STEP 1/2] Running DISM /RestoreHealth..." -ForegroundColor Cyan
Write-Host "This repairs the Windows component store..." -ForegroundColor Gray
Write-Host ""

try {
    $dismResult = DISM /Online /Cleanup-Image /RestoreHealth
    $dismResult | Out-String | Write-Host

    if ($LASTEXITCODE -eq 0) {
        Write-Host "✅ DISM completed successfully" -ForegroundColor Green
    } else {
        Write-Host "[WARNING] DISM completed with exit code: $LASTEXITCODE" -ForegroundColor Yellow
    }
}
catch {
    Write-Host "[ERROR] DISM failed: $_" -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "---" -ForegroundColor DarkGray
Write-Host ""

# Step 2: SFC Scan
Write-Host "[STEP 2/2] Running SFC /scannow..." -ForegroundColor Cyan
Write-Host "This scans and repairs system files..." -ForegroundColor Gray
Write-Host ""

try {
    $sfcResult = sfc /scannow
    $sfcResult | Out-String | Write-Host

    if ($LASTEXITCODE -eq 0) {
        Write-Host "✅ SFC completed successfully" -ForegroundColor Green
    } else {
        Write-Host "[WARNING] SFC completed with exit code: $LASTEXITCODE" -ForegroundColor Yellow
    }
}
catch {
    Write-Host "[ERROR] SFC failed: $_" -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "=== REPAIR COMPLETE ===" -ForegroundColor Cyan
Write-Host "✅ Windows image repair finished" -ForegroundColor Green
Write-Host ""
Write-Host "Check the output above for details." -ForegroundColor Gray
Write-Host "If issues persist, a system restart may be required." -ForegroundColor Yellow

# QuickClean - Advanced System Cleanup
# Generated: $(Get-Date)
# NOTE: This script requires Administrator privileges for full functionality

$ErrorActionPreference = 'Stop'
$logDir = "$env:ProgramData\QuickClean"
$null = New-Item -ItemType Directory -Path $logDir -Force -ErrorAction SilentlyContinue
$log = Join-Path $logDir ("QuickClean_{0:yyyy-MM-dd_HH-mm-ss}.log" -f (Get-Date))

function Write-Log {
    param([string]$Message)
    $line = "[{0}] {1}" -f (Get-Date -Format "yyyy-MM-dd HH:mm:ss"), $Message
    $line | Tee-Object -FilePath $log -Append
}

function Format-Size {
    param([double]$Bytes)
    switch ($Bytes) {
        {$_ -ge 1TB} { return ("{0:N2} TB" -f ($Bytes/1TB)) }
        {$_ -ge 1GB} { return ("{0:N2} GB" -f ($Bytes/1GB)) }
        {$_ -ge 1MB} { return ("{0:N2} MB" -f ($Bytes/1MB)) }
        {$_ -ge 1KB} { return ("{0:N2} KB" -f ($Bytes/1KB)) }
        default { return ("{0} B" -f [math]::Round($Bytes)) }
    }
}

function Get-SizeBytes {
    param([string[]]$Paths)
    $total = 0
    foreach ($p in $Paths) {
        if (Test-Path $p) {
            Get-ChildItem -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue |
                Where-Object { -not $_.PSIsContainer } |
                ForEach-Object { $total += ($_.Length) }
        }
    }
    return [double]$total
}

Write-Log "=== QuickClean started ==="
$sw = [System.Diagnostics.Stopwatch]::StartNew()

# Check admin
$IsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
Write-Log "Running as admin: $IsAdmin"

# Define paths
$tempPaths = @($env:TEMP, $env:TMP, "$env:USERPROFILE\AppData\Local\Temp")
$sysTempPaths = @("$env:windir\Temp")

# Measure before
Write-Log "Measuring space before cleanup..."
$beforeUser = Get-SizeBytes -Paths $tempPaths
$beforeSys = Get-SizeBytes -Paths $sysTempPaths

# Clean user temp
Write-Log "Cleaning USER temp folders..."
foreach ($p in $tempPaths) {
    if (Test-Path $p) {
        try {
            Get-ChildItem -LiteralPath $p -Force -Recurse -ErrorAction SilentlyContinue |
                Remove-Item -Force -Recurse -ErrorAction SilentlyContinue
            Write-Log "✔ Cleaned: $p"
        } catch {
            Write-Log "⚠ Skipped (in use): $p"
        }
    }
}

# Clean system temp
if ($IsAdmin) {
    Write-Log "Cleaning SYSTEM temp folders..."
    foreach ($p in $sysTempPaths) {
        if (Test-Path $p) {
            try {
                Get-ChildItem -LiteralPath $p -Force -Recurse -ErrorAction SilentlyContinue |
                    Remove-Item -Force -Recurse -ErrorAction SilentlyContinue
                Write-Log "✔ Cleaned: $p"
            } catch {
                Write-Log "⚠ Skipped (in use): $p"
            }
        }
    }
} else {
    Write-Log "Skipping SYSTEM temp (run as Administrator to clean)."
}

# Recycle Bin
try {
    Write-Log "Emptying Recycle Bin..."
    Clear-RecycleBin -Force -ErrorAction SilentlyContinue
    Write-Log "✔ Recycle Bin emptied"
} catch {
    Write-Log "⚠ Recycle Bin not emptied"
}

# DNS Cache
try {
    Write-Log "Flushing DNS cache..."
    ipconfig /flushdns | Out-Null
    Write-Log "✔ DNS cache flushed"
} catch {
    Write-Log "⚠ DNS flush failed"
}

# Measure after
$afterUser = Get-SizeBytes -Paths $tempPaths
$afterSys = Get-SizeBytes -Paths $sysTempPaths
$freedUser = [math]::Max(0, $beforeUser - $afterUser)
$freedSys = [math]::Max(0, $beforeSys - $afterSys)
$totalFreed = $freedUser + $freedSys

Write-Log "Freed (User temp):  $(Format-Size $freedUser)"
Write-Log "Freed (System temp): $(Format-Size $freedSys)"
Write-Log "Freed (Total):      $(Format-Size $totalFreed)"

$sw.Stop()
Write-Log "Elapsed: $($sw.Elapsed)"
Write-Log "=== QuickClean finished ==="

Write-Host ""
Write-Host "✅ Cleanup complete." -ForegroundColor Green
Write-Host "Freed total: $(Format-Size $totalFreed)"
Write-Host "Detailed log: $log"
if (-not $IsAdmin) {
    Write-Host "Tip: Run as Administrator to also clean system temp." -ForegroundColor Yellow
}

network_tools.template:
# Show Saved WiFi Passwords
# Generated: $(Get-Date)

Write-Host "=== SAVED WIFI PASSWORDS ===" -ForegroundColor Cyan
Write-Host ""

$Profiles = (netsh wlan show profiles) | Select-String "All User Profile" | ForEach-Object { ($_ -split ":")[1].Trim() }

if ($Profiles.Count -eq 0) {
    Write-Host "No saved WiFi profiles found" -ForegroundColor Yellow
    exit 0
}

foreach ($Profile in $Profiles) {
    Write-Host "Network: $Profile" -ForegroundColor Yellow

    $Password = (netsh wlan show profile name="$Profile" key=clear) | Select-String "Key Content" | ForEach-Object { ($_ -split ":")[1].Trim() }

    if ($Password) {
        Write-Host "  Password: $Password" -ForegroundColor Green
    } else {
        Write-Host "  Password: (Open Network or Not Available)" -ForegroundColor Gray
    }
    Write-Host ""
}

Write-Host "=== COMPLETE ===" -ForegroundColor Green

# Port Scanner
# Generated: $(Get-Date)

$Hostname = "{{hostname}}"
$Port = {{port}}

Write-Host "Scanning port $Port on $Hostname..." -ForegroundColor Cyan

try {
    $Connection = Test-NetConnection -ComputerName $Hostname -Port $Port -WarningAction SilentlyContinue

    if ($Connection.TcpTestSucceeded) {
        Write-Host "Port $Port is OPEN" -ForegroundColor Green
    }
    else {
        Write-Host "Port $Port is CLOSED" -ForegroundColor Red
    }

    Write-Host ""
    Write-Host "Remote Address: $($Connection.RemoteAddress)" -ForegroundColor Yellow
    Write-Host "Ping Success: $($Connection.PingSucceeded)" -ForegroundColor Yellow
}
catch {
    Write-Host "Error scanning port: $_" -ForegroundColor Red
}

security.template:
# Windows Event Log Hunter
# Generated: $(Get-Date)
# NOTE: This script requires Administrator privileges

$EventIDsInput = "{{event_ids}}"
$HoursBack = "{{hours_back}}"
$MaxEvents = "{{max_events}}"

# Set defaults
if ([string]::IsNullOrWhiteSpace($HoursBack)) { $HoursBack = 24 }
if ([string]::IsNullOrWhiteSpace($MaxEvents)) { $MaxEvents = 100 }

Write-Host "=== WINDOWS EVENT LOG HUNTER ===" -ForegroundColor Cyan
Write-Host ""

# Parse Event IDs
$EventIDs = $EventIDsInput -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -match '^\d+$' }

if ($EventIDs.Count -eq 0) {
    Write-Host "[ERROR] No Event IDs provided" -ForegroundColor Red
    Write-Host "Enter Event IDs (e.g., 4624,4625,4672)" -ForegroundColor Yellow
    exit 1
}

Write-Host "Hunting for Event IDs: $($EventIDs -join ', ')" -ForegroundColor Yellow
Write-Host "Time Range: Last $HoursBack hours" -ForegroundColor Gray
Write-Host "Max Events: $MaxEvents" -ForegroundColor Gray
Write-Host ""

$StartTime = (Get-Date).AddHours(-$HoursBack)

# Hunt in Security log
Write-Host "[SECURITY LOG]" -ForegroundColor Cyan
try {
    $SecurityEvents = Get-WinEvent -FilterHashtable @{
        LogName = 'Security'
        ID = $EventIDs
        StartTime = $StartTime
    } -MaxEvents $MaxEvents -ErrorAction SilentlyContinue

    if ($SecurityEvents) {
        Write-Host "Found $($SecurityEvents.Count) event(s)" -ForegroundColor Green
        Write-Host ""

        foreach ($Event in $SecurityEvents) {
            Write-Host "[Event ID: $($Event.Id)]" -ForegroundColor Yellow
            Write-Host "  Time: $($Event.TimeCreated)" -ForegroundColor Gray
            Write-Host "  User: $($Event.Properties[1].Value)" -ForegroundColor Cyan
            Write-Host "  Computer: $($Event.MachineName)" -ForegroundColor Gray
            Write-Host ""
        }
    } else {
        Write-Host "No events found" -ForegroundColor Yellow
    }
} catch {
    Write-Host "Error querying Security log: $_" -ForegroundColor Red
}

# Hunt in System log
$SystemEventIDs = $EventIDs | Where-Object { $_ -in @('1074','1076','6005','6006','6008') }
if ($SystemEventIDs.Count -gt 0) {
    Write-Host ""
    Write-Host "[SYSTEM LOG]" -ForegroundColor Cyan
    try {
        $SystemEvents = Get-WinEvent -FilterHashtable @{
            LogName = 'System'
            ID = $SystemEventIDs
            StartTime = $StartTime
        } -MaxEvents $MaxEvents -ErrorAction SilentlyContinue

        if ($SystemEvents) {
            Write-Host "Found $($SystemEvents.Count) event(s)" -ForegroundColor Green
            Write-Host ""

            foreach ($Event in $SystemEvents) {
                Write-Host "[Event ID: $($Event.Id)]" -ForegroundColor Yellow
                Write-Host "  Time: $($Event.TimeCreated)" -ForegroundColor Gray
                Write-Host "  Computer: $($Event.MachineName)" -ForegroundColor Gray
                Write-Host ""
            }
        } else {
            Write-Host "No events found" -ForegroundColor Yellow
        }
    } catch {
        Write-Host "Error querying System log: $_" -ForegroundColor Red
    }
}

Write-Host "=== EVENT HUNT COMPLETE ===" -ForegroundColor Green

windows_updates.template:
# List Recent Windows Updates
# Generated: $(Get-Date)

Write-Host "=== LATEST 10 INSTALLED UPDATES ===" -ForegroundColor Cyan
Write-Host ""

$RecentUpdates = Get-HotFix | Sort-Object InstalledOn -Descending | Select-Object -First 10

if ($RecentUpdates) {
    foreach ($Update in $RecentUpdates) {
        Write-Host "KB: $($Update.HotFixID)" -ForegroundColor Yellow
        Write-Host "Installed: $($Update.InstalledOn)" -ForegroundColor Gray
        Write-Host "Description: $($Update.Description)" -ForegroundColor Gray
        Write-Host "---" -ForegroundColor DarkGray
        Write-Host ""
    }
} else {
    Write-Host "No updates found." -ForegroundColor Red
}

# Remove Windows Update
# Generated: $(Get-Date)
# NOTE: This script requires Administrator privileges

$KBNumber = "{{kb_number}}"

Write-Host "=== REMOVE WINDOWS UPDATE KB$KBNumber ===" -ForegroundColor Cyan
Write-Host ""

# Check if running as administrator
$IsAdmin = ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

if (-not $IsAdmin) {
    Write-Host "[!] WARNING: This script is not running as Administrator" -ForegroundColor Red
    Write-Host "    The uninstall operation will likely fail without admin privileges" -ForegroundColor Yellow
    Write-Host ""
}

# Check if the update is installed
Write-Host "Checking if KB$KBNumber is installed..." -ForegroundColor Cyan
$InstalledUpdate = Get-HotFix | Where-Object { $_.HotFixID -eq "KB$KBNumber" }

if ($InstalledUpdate) {
    Write-Host "[FOUND] KB$KBNumber is currently installed" -ForegroundColor Yellow
    Write-Host "  Installed On: $($InstalledUpdate.InstalledOn)" -ForegroundColor Gray
    Write-Host "  Description: $($InstalledUpdate.Description)" -ForegroundColor Gray
    Write-Host ""

    Write-Host "Attempting to uninstall KB$KBNumber..." -ForegroundColor Cyan
    Write-Host "This may take several minutes..." -ForegroundColor Yellow
    Write-Host ""

    try {
        # Use wusa.exe to uninstall the update
        $Process = Start-Process -FilePath "wusa.exe" -ArgumentList "/uninstall /kb:$KBNumber /quiet /norestart" -Wait -PassThru

        if ($Process.ExitCode -eq 0) {
            Write-Host "[SUCCESS] KB$KBNumber has been uninstalled successfully!" -ForegroundColor Green
            Write-Host ""
            Write-Host "A system restart may be required for changes to take effect." -ForegroundColor Yellow
        } elseif ($Process.ExitCode -eq 2359302) {
            Write-Host "[INFO] Update is not installed or already removed" -ForegroundColor Yellow
        } else {
            Write-Host "[ERROR] Uninstallation failed with exit code: $($Process.ExitCode)" -ForegroundColor Red
            Write-Host ""
            Write-Host "Common exit codes:" -ForegroundColor Gray
            Write-Host "  2359302 - Update not found" -ForegroundColor Gray
            Write-Host "  5 - Access denied (run as Administrator)" -ForegroundColor Gray
        }
    }
    catch {
        Write-Host "[ERROR] Failed to uninstall update: $_" -ForegroundColor Red
    }
} else {
    Write-Host "[NOT FOUND] KB$KBNumber is not currently installed" -ForegroundColor Green
    Write-Host "No action needed." -ForegroundColor Gray
}

domain_migration.template:
# Domain Migration - Smart Backup + BreakGlass
# Generated: $(Get-Date)
# NOTE: This script requires Administrator privileges

Write-Host "=== DOMAIN MIGRATION SMART BACKUP STARTED ===" -ForegroundColor Cyan
Write-Host ""

if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]"Administrator")) {
    Write-Error "Run this script as Administrator."
    exit 1
}

# Create/Verify BreakGlass Admin
Write-Host "=== Verifying Local Emergency Admin Account ===" -ForegroundColor Cyan

$BreakGlassUserName = "IT-BreakGlass"
$BreakGlassPlainPass = "S0mething!VeryStr0ng#2026"
$BreakGlassSecurePass = ConvertTo-SecureString $BreakGlassPlainPass -AsPlainText -Force

$ExistingLocalUser = Get-LocalUser -Name $BreakGlassUserName -ErrorAction SilentlyContinue

if (-not $ExistingLocalUser) {
    Write-Host "Creating local emergency admin: $BreakGlassUserName" -ForegroundColor Yellow
    New-LocalUser -Name $BreakGlassUserName -Password $BreakGlassSecurePass -FullName "IT Emergency Admin" -Description "Local emergency admin account for domain migration / recovery" -PasswordNeverExpires:$true -UserMayNotChangePassword:$true -AccountNeverExpires:$true
} else {
    Write-Host "Local emergency admin already exists" -ForegroundColor Green
    if ($ExistingLocalUser.Enabled -eq $false) {
        Enable-LocalUser -Name $BreakGlassUserName
        Write-Host "Enabled existing $BreakGlassUserName account" -ForegroundColor Green
    }
}

$IsBreakGlassAdmin = Get-LocalGroupMember -Group "Administrators" -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "*\$BreakGlassUserName" }

if (-not $IsBreakGlassAdmin) {
    Add-LocalGroupMember -Group "Administrators" -Member $BreakGlassUserName
    Write-Host "Added $BreakGlassUserName to Administrators group" -ForegroundColor Green
} else {
    Write-Host "$BreakGlassUserName already member of Administrators" -ForegroundColor Green
}

Write-Host "✅ Emergency Admin Verified" -ForegroundColor Green
Write-Host ""

# Detect real user profile
$ExcludedPatterns = @('^Public$','^Default$','^Default User$','^All Users$','^Administrator$','^WDAGUtilityAccount$','^TEMP\.')

$UserProfile = Get-ChildItem 'C:\Users' -Directory | Where-Object {
    $name = $_.Name
    ($ExcludedPatterns | Where-Object { $name -match $_ }).Count -eq 0 -and (Test-Path (Join-Path $_.FullName 'NTUSER.DAT'))
} | Sort-Object LastWriteTime -Descending | Select-Object -First 1

if (-not $UserProfile) {
    Write-Error "No valid user profile found."
    exit 1
}

$User = $UserProfile.Name
$ProfileDir = $UserProfile.FullName
$BackupRoot = "C:\DomainMigration\$User"

Write-Host "Detected user: $User" -ForegroundColor Cyan
New-Item -ItemType Directory -Path $BackupRoot -Force | Out-Null

# Resolve SID
$ProfileListKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList'
$Sid = $null

foreach ($p in Get-ChildItem $ProfileListKey) {
    $pi = Get-ItemProperty $p.PSPath -ErrorAction SilentlyContinue
    if ($pi.ProfileImagePath -ieq $ProfileDir) {
        $Sid = Split-Path $p.PSChildName -Leaf
        break
    }
}

if (-not $Sid) {
    Write-Error "Could not resolve SID for user profile: $ProfileDir"
    exit 1
}

# Get shell folders
$UserShellKey = "Registry::HKEY_USERS\$Sid\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders"
$UShell = Get-ItemProperty $UserShellKey

function Expand-UserPath { param($p) [Environment]::ExpandEnvironmentVariables($p) }

$DesktopPath = Expand-UserPath $UShell.Desktop
$DocsPath = Expand-UserPath $UShell.Personal
$PicturesPath = Expand-UserPath $UShell.'My Pictures'

$DesktopInOD = $DesktopPath -like '*OneDrive*'
$DocsInOD = $DocsPath -like '*OneDrive*'
$PicturesInOD = $PicturesPath -like '*OneDrive*'

Write-Host "Desktop:   $DesktopPath (OneDrive: $DesktopInOD)" -ForegroundColor Gray
Write-Host "Documents: $DocsPath (OneDrive: $DocsInOD)" -ForegroundColor Gray
Write-Host "Pictures:  $PicturesPath (OneDrive: $PicturesInOD)" -ForegroundColor Gray
Write-Host ""

# Smart backup (skip if in OneDrive)
$FoldersToCheck = @(
    @{Name="Desktop"; Path=$DesktopPath; InOD=$DesktopInOD},
    @{Name="Documents"; Path=$DocsPath; InOD=$DocsInOD},
    @{Name="Pictures"; Path=$PicturesPath; InOD=$PicturesInOD}
)

foreach ($f in $FoldersToCheck) {
    if (-not $f.InOD -and (Test-Path $f.Path)) {
        Write-Host "Backing up local $($f.Name)..." -ForegroundColor Yellow
        robocopy $f.Path "$BackupRoot\$($f.Name)" /E /COPY:DAT /R:1 /W:1 /NFL /NDL | Out-Null
    } else {
        if ($f.InOD) {
            Write-Host "$($f.Name) is in OneDrive – skipping local backup" -ForegroundColor Cyan
        }
    }
}

# Additional folders
$ExtraFolders = @("Downloads","Favorites")
foreach ($Folder in $ExtraFolders) {
    $Src = Join-Path $ProfileDir $Folder
    if (Test-Path $Src) {
        Write-Host "Backing up $Folder..." -ForegroundColor Yellow
        robocopy $Src "$BackupRoot\$Folder" /E /COPY:DAT /R:1 /W:1 /NFL /NDL | Out-Null
    }
}

# Outlook
$Outlook = Join-Path $ProfileDir "AppData\Roaming\Microsoft\Outlook"
if (Test-Path $Outlook) {
    Write-Host "Backing up Outlook..." -ForegroundColor Yellow
    robocopy $Outlook "$BackupRoot\Outlook" /E /COPY:DAT /R:1 /W:1 /NFL /NDL | Out-Null
}

# Browsers
$Chrome = Join-Path $ProfileDir "AppData\Local\Google\Chrome\User Data"
if (Test-Path $Chrome) {
    Write-Host "Backing up Chrome..." -ForegroundColor Yellow
    robocopy $Chrome "$BackupRoot\Chrome" /E /XJ /COPY:DAT /R:1 /W:1 /NFL /NDL | Out-Null
}

$Edge = Join-Path $ProfileDir "AppData\Local\Microsoft\Edge\User Data"
if (Test-Path $Edge) {
    Write-Host "Backing up Edge..." -ForegroundColor Yellow
    robocopy $Edge "$BackupRoot\Edge" /E /XJ /COPY:DAT /R:1 /W:1 /NFL /NDL | Out-Null
}

$Firefox = Join-Path $ProfileDir "AppData\Roaming\Mozilla"
if (Test-Path $Firefox) {
    Write-Host "Backing up Firefox..." -ForegroundColor Yellow
    robocopy $Firefox "$BackupRoot\Firefox" /E /COPY:DAT /R:1 /W:1 /NFL /NDL | Out-Null
}

# Printer snapshot
$PrinterDir = Join-Path $BackupRoot "Printers"
New-Item -ItemType Directory -Path $PrinterDir -Force | Out-Null

try {
    Import-Module PrintManagement -ErrorAction Stop
    $printers = Get-Printer | Sort-Object Name
    $snapshot = [pscustomobject]@{
        ComputerName = $env:COMPUTERNAME
        CollectedAt = (Get-Date).ToString("s")
        Printers = $printers
    }
    $snapshot | ConvertTo-Json -Depth 5 | Out-File "$PrinterDir\Printers.json" -Encoding UTF8
    Write-Host "Printer backup completed" -ForegroundColor Green
} catch {
    Write-Warning "Printer module not available. Skipping printer backup."
}

# Summary
$Summary = @"
User: $User
BackupRoot: $BackupRoot
Completed: $(Get-Date)
"@

$Summary | Out-File "$BackupRoot\BackupSummary.txt" -Encoding UTF8
New-Item "$BackupRoot\BACKUP_COMPLETED.txt" -ItemType File -Force | Out-Null

Write-Host ""
Write-Host "=== SMART BACKUP COMPLETED SUCCESSFULLY ===" -ForegroundColor Green
Write-Host "Backup location: $BackupRoot" -ForegroundColor Cyan

