browser_tools.template:
# Update Browser using Winget
# Generated: $(Get-Date)

$Browser = "{{browser}}"

Write-Host "=== UPDATE BROWSER ===" -ForegroundColor Cyan
Write-Host ""

# Check if winget is available
try {
    $WingetVersion = winget --version
    Write-Host "Winget version: $WingetVersion" -ForegroundColor Gray
    Write-Host ""
}
catch {
    Write-Host "[ERROR] Winget is not installed or not available" -ForegroundColor Red
    Write-Host "Please install Windows Package Manager (winget) first" -ForegroundColor Yellow
    exit 1
}

# Get browser name for display
$BrowserName = switch ($Browser) {
    "Google.Chrome" { "Google Chrome" }
    "Mozilla.Firefox" { "Mozilla Firefox" }
    "Microsoft.Edge" { "Microsoft Edge" }
    "BraveSoftware.BraveBrowser" { "Brave Browser" }
    "Opera.Opera" { "Opera" }
    "Vivaldi.Vivaldi" { "Vivaldi" }
    default { $Browser }
}

Write-Host "Updating $BrowserName..." -ForegroundColor Yellow
Write-Host "Package ID: $Browser" -ForegroundColor Gray
Write-Host ""

try {
    # Check if browser is installed
    Write-Host "Checking if $BrowserName is installed..." -ForegroundColor Cyan
    $InstalledApp = winget list --id $Browser --exact 2>$null

    if ($LASTEXITCODE -ne 0) {
        Write-Host "[NOT FOUND] $BrowserName is not installed" -ForegroundColor Yellow
        Write-Host "Would you like to install it instead? Run: winget install $Browser" -ForegroundColor Gray
        exit 0
    }

    Write-Host "[FOUND] $BrowserName is installed" -ForegroundColor Green
    Write-Host ""

    # Upgrade the browser
    Write-Host "Starting upgrade process..." -ForegroundColor Cyan
    Write-Host "This may take a few minutes..." -ForegroundColor Gray
    Write-Host ""

    winget upgrade $Browser --silent --accept-source-agreements --accept-package-agreements

    if ($LASTEXITCODE -eq 0) {
        Write-Host ""
        Write-Host "✅ SUCCESS: $BrowserName has been updated!" -ForegroundColor Green
    } elseif ($LASTEXITCODE -eq -1978335189) {
        Write-Host ""
        Write-Host "[INFO] $BrowserName is already up to date" -ForegroundColor Cyan
    } else {
        Write-Host ""
        Write-Host "[WARNING] Update completed with exit code: $LASTEXITCODE" -ForegroundColor Yellow
    }
}
catch {
    Write-Host "[ERROR] Failed to update $BrowserName: $_" -ForegroundColor Red
}

# Clear All Browser Caches
# Generated: $(Get-Date)

Write-Host "=== CLEAR ALL BROWSER CACHES ===" -ForegroundColor Cyan
Write-Host ""

Write-Host "Stopping browsers..." -ForegroundColor Yellow
Write-Host "  Lockout Threshold: $LockoutThreshold attempts" -ForegroundColor Gray
Write-Host "  Lockout Duration: $LockoutDuration minutes" -ForegroundColor Gray
Write-Host "  Min Password Length: $MinPasswordLength characters" -ForegroundColor Gray
Write-Host "  Max Password Age: $MaxPasswordAge days" -ForegroundColor Gray
Write-Host "  Password History: $PasswordHistory passwords" -ForegroundColor Gray
Write-Host ""

# Check if running on a Domain Controller
$IsDC = (Get-WmiObject -Class Win32_ComputerSystem).DomainRole -ge 4
if (-not $IsDC) {
    Write-Host "[!] WARNING: This machine is not a Domain Controller" -ForegroundColor Red
    Write-Host "This script should only be run on Domain Controllers" -ForegroundColor Yellow
    $continue = Read-Host "Continue anyway? (y/N)"
    if ($continue -ne 'y') { exit }
}

Write-Host "[1/8] Configuring Account Lockout Policy..." -ForegroundColor Cyan
try {
    # Set account lockout threshold
    net accounts /lockoutthreshold:$LockoutThreshold /lockoutduration:$LockoutDuration /lockoutwindow:$LockoutDuration
    Write-Host "  ✅ Account lockout: $LockoutThreshold attempts, $LockoutDuration min duration" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to set account lockout policy" -ForegroundColor Red
}

Write-Host ""
Write-Host "[2/8] Configuring Password Policy..." -ForegroundColor Cyan
try {
    # Set minimum password length and complexity
    net accounts /minpwlen:$MinPasswordLength /maxpwage:$MaxPasswordAge /minpwage:1 /uniquepw:$PasswordHistory
    Write-Host "  ✅ Min password length: $MinPasswordLength characters" -ForegroundColor Green
    Write-Host "  ✅ Max password age: $MaxPasswordAge days" -ForegroundColor Green
    Write-Host "  ✅ Password history: $PasswordHistory passwords" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to set password policy" -ForegroundColor Red
}

Write-Host ""
Write-Host "[3/8] Disabling SMBv1 Protocol..." -ForegroundColor Cyan
try {
    Set-SmbServerConfiguration -EnableSMB1Protocol $false -Force
    Write-Host "  ✅ SMBv1 disabled (protects against WannaCry/EternalBlue)" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to disable SMBv1" -ForegroundColor Red
}

Write-Host ""
Write-Host "[4/8] Enabling Windows Firewall..." -ForegroundColor Cyan
try {
    Set-NetFirewallProfile -Profile Domain,Public,Private -Enabled True
    Write-Host "  ✅ Firewall enabled on all profiles" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to enable firewall" -ForegroundColor Red
}

Write-Host ""
Write-Host "[5/8] Configuring Audit Policies..." -ForegroundColor Cyan
try {
    # Enable critical audit policies
    auditpol /set /category:"Account Logon" /success:enable /failure:enable
    auditpol /set /category:"Account Management" /success:enable /failure:enable
    auditpol /set /category:"Logon/Logoff" /success:enable /failure:enable
    auditpol /set /category:"Policy Change" /success:enable /failure:enable
    auditpol /set /category:"Privilege Use" /success:enable /failure:enable
    Write-Host "  ✅ Critical audit policies enabled" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to configure audit policies" -ForegroundColor Red
}

Write-Host ""
Write-Host "[6/8] Disabling Guest Account..." -ForegroundColor Cyan
try {
    net user guest /active:no
    Write-Host "  ✅ Guest account disabled" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to disable guest account" -ForegroundColor Red
}

Write-Host ""
Write-Host "[7/8] Configuring RDP Security..." -ForegroundColor Cyan
try {
    # Require NLA for RDP
    Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name 'UserAuthentication' -Value 1
    # Set encryption level to high
    Set-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' -Name 'MinEncryptionLevel' -Value 3
    Write-Host "  ✅ RDP requires Network Level Authentication" -ForegroundColor Green
    Write-Host "  ✅ RDP encryption set to High" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to configure RDP security" -ForegroundColor Red
}

Write-Host ""
Write-Host "[8/8] Disabling Unnecessary Services..." -ForegroundColor Cyan
$ServicesToDisable = @('RemoteRegistry', 'SSDPSRV', 'upnphost')
foreach ($Service in $ServicesToDisable) {
    try {
        $Svc = Get-Service -Name $Service -ErrorAction SilentlyContinue
        if ($Svc) {
            Stop-Service -Name $Service -Force -ErrorAction SilentlyContinue
            Set-Service -Name $Service -StartupType Disabled
            Write-Host "  ✅ Disabled: $Service" -ForegroundColor Green
        }
    } catch {
        Write-Host "  ⚠ Could not disable: $Service" -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "=== BASIC HARDENING COMPLETE ===" -ForegroundColor Green
Write-Host ""
Write-Host "Additional Recommendations:" -ForegroundColor Yellow
Write-Host "  • Run Windows Update regularly" -ForegroundColor Gray
Write-Host "  • Enable BitLocker on system drives" -ForegroundColor Gray
Write-Host "  • Implement least privilege access" -ForegroundColor Gray
Write-Host "  • Use separate admin accounts" -ForegroundColor Gray
Write-Host "  • Enable Advanced Threat Protection" -ForegroundColor Gray
Write-Host ""
Write-Host "[!] IMPORTANT: Test these changes in a non-production environment first" -ForegroundColor Red

m365.template:
# Connect to Microsoft 365 Services
# Generated: $(Get-Date)
# NOTE: Requires Microsoft 365 PowerShell modules

$AdminEmail = "{{admin_email}}"

Write-Host "=== MICROSOFT 365 CONNECTION ===" -ForegroundColor Cyan
Write-Host ""
Write-Host "Admin Account: $AdminEmail" -ForegroundColor Yellow
Write-Host ""

# Check for required modules
$RequiredModules = @(
    'ExchangeOnlineManagement',
    'AzureAD',
    'MicrosoftTeams'
)

Write-Host "Checking required modules..." -ForegroundColor Cyan
foreach ($Module in $RequiredModules) {
    if (Get-Module -ListAvailable -Name $Module) {
        Write-Host "  ✅ $Module installed" -ForegroundColor Green
    } else {
        Write-Host "  ❌ $Module NOT installed" -ForegroundColor Red
        Write-Host "     Install with: Install-Module $Module -Force" -ForegroundColor Yellow
    }
}

Write-Host ""
Write-Host "Connecting to services..." -ForegroundColor Cyan
Write-Host ""

# Connect to Exchange Online
try {
    Write-Host "[1/3] Connecting to Exchange Online..." -ForegroundColor Yellow
    Connect-ExchangeOnline -UserPrincipalName $AdminEmail -ShowProgress $true
    Write-Host "  ✅ Connected to Exchange Online" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to connect to Exchange Online: $_" -ForegroundColor Red
}

Write-Host ""

# Connect to Azure AD
try {
    Write-Host "[2/3] Connecting to Azure AD..." -ForegroundColor Yellow
    Connect-AzureAD -AccountId $AdminEmail
    Write-Host "  ✅ Connected to Azure AD" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to connect to Azure AD: $_" -ForegroundColor Red
}

Write-Host ""

# Connect to Microsoft Teams
try {
    Write-Host "[3/3] Connecting to Microsoft Teams..." -ForegroundColor Yellow
    Connect-MicrosoftTeams -AccountId $AdminEmail
    Write-Host "  ✅ Connected to Microsoft Teams" -ForegroundColor Green
} catch {
    Write-Host "  ❌ Failed to connect to Teams: $_" -ForegroundColor Red
}

Write-Host ""
Write-Host "=== CONNECTION COMPLETE ===" -ForegroundColor Green
Write-Host "You are now connected to Microsoft 365 services" -ForegroundColor Cyan

# Get Microsoft 365 User Information
# Generated: $(Get-Date)
# NOTE: Must be connected to M365 (use Connect to Microsoft 365 script first)

$UserEmail = "{{user_email}}"

Write-Host "=== M365 USER INFORMATION ===" -ForegroundColor Cyan
Write-Host "User: $UserEmail" -ForegroundColor Yellow
Write-Host ""

# Get Azure AD User
try {
    Write-Host "[Azure AD Information]" -ForegroundColor Cyan
    $AzureUser = Get-AzureADUser -ObjectId $UserEmail -ErrorAction Stop

    Write-Host "  Display Name: $($AzureUser.DisplayName)" -ForegroundColor Gray
    Write-Host "  User Principal Name: $($AzureUser.UserPrincipalName)" -ForegroundColor Gray
    Write-Host "  Object ID: $($AzureUser.ObjectId)" -ForegroundColor Gray
    Write-Host "  Account Enabled: $($AzureUser.AccountEnabled)" -ForegroundColor $(if($AzureUser.AccountEnabled){'Green'}else{'Red'})
    Write-Host "  Department: $($AzureUser.Department)" -ForegroundColor Gray
    Write-Host "  Job Title: $($AzureUser.JobTitle)" -ForegroundColor Gray
    Write-Host "  Office Location: $($AzureUser.PhysicalDeliveryOfficeName)" -ForegroundColor Gray
    Write-Host "  Mobile: $($AzureUser.Mobile)" -ForegroundColor Gray
    Write-Host ""
} catch {
    Write-Host "  ❌ Error retrieving Azure AD info: $_" -ForegroundColor Red
    Write-Host ""
}

# Get Mailbox Information
try {
    Write-Host "[Exchange Online Mailbox]" -ForegroundColor Cyan
    $Mailbox = Get-Mailbox -Identity $UserEmail -ErrorAction Stop

    Write-Host "  Mailbox Type: $($Mailbox.RecipientTypeDetails)" -ForegroundColor Gray
    Write-Host "  Primary SMTP: $($Mailbox.PrimarySmtpAddress)" -ForegroundColor Gray
    Write-Host "  Mailbox Size: " -NoNewline -ForegroundColor Gray

    $Stats = Get-MailboxStatistics -Identity $UserEmail
    Write-Host "$($Stats.TotalItemSize)" -ForegroundColor Yellow
    Write-Host "  Item Count: $($Stats.ItemCount)" -ForegroundColor Gray
    Write-Host "  Last Logon: $($Stats.LastLogonTime)" -ForegroundColor Gray
    Write-Host ""
} catch {
    Write-Host "  ❌ Error retrieving mailbox info: $_" -ForegroundColor Red
    Write-Host ""
}

# Get License Information
try {
    Write-Host "[License Information]" -ForegroundColor Cyan
    $Licenses = Get-AzureADUserLicenseDetail -ObjectId $UserEmail -ErrorAction Stop

    if ($Licenses) {
        foreach ($License in $Licenses) {
            Write-Host "  ✅ $($License.SkuPartNumber)" -ForegroundColor Green
        }
    } else {
        Write-Host "  No licenses assigned" -ForegroundColor Yellow
    }
    Write-Host ""
} catch {
    Write-Host "  ❌ Error retrieving license info: $_" -ForegroundColor Red
    Write-Host ""
}

Write-Host "=== REPORT COMPLETE ===" -ForegroundColor Green

# Grant Mailbox Permissions
# Generated: $(Get-Date)
# NOTE: Must be connected to Exchange Online

$TargetMailbox = "{{target_mailbox}}"
$UserEmail = "{{user_email}}"
$PermissionType = "{{permission_type}}"

Write-Host "=== GRANT MAILBOX PERMISSIONS ===" -ForegroundColor Cyan
Write-Host ""
Write-Host "Target Mailbox: $TargetMailbox" -ForegroundColor Yellow
Write-Host "User: $UserEmail" -ForegroundColor Yellow
Write-Host "Permission: $PermissionType" -ForegroundColor Yellow
Write-Host ""

try {
    switch ($PermissionType) {
        "FullAccess" {
            Add-MailboxPermission -Identity $TargetMailbox -User $UserEmail -AccessRights FullAccess -InheritanceType All -AutoMapping $true
            Write-Host "✅ Full Access granted successfully!" -ForegroundColor Green
            Write-Host "The mailbox will auto-map in Outlook" -ForegroundColor Cyan
        }
        "SendAs" {
            Add-RecipientPermission -Identity $TargetMailbox -Trustee $UserEmail -AccessRights SendAs -Confirm:$false
            Write-Host "✅ Send As permission granted successfully!" -ForegroundColor Green
            Write-Host "User can send emails as $TargetMailbox" -ForegroundColor Cyan
        }
        "SendOnBehalf" {
            Set-Mailbox -Identity $TargetMailbox -GrantSendOnBehalfTo @{Add=$UserEmail}
            Write-Host "✅ Send on Behalf permission granted successfully!" -ForegroundColor Green
            Write-Host "User can send emails on behalf of $TargetMailbox" -ForegroundColor Cyan
        }
    }

    Write-Host ""
    Write-Host "[NOTE] Changes may take up to 60 minutes to propagate" -ForegroundColor Yellow

} catch {
    Write-Host "❌ Error granting permissions: $_" -ForegroundColor Red
}

# List All Shared Mailboxes
# Generated: $(Get-Date)
# NOTE: Must be connected to Exchange Online

Write-Host "=== SHARED MAILBOXES REPORT ===" -ForegroundColor Cyan
Write-Host ""
Write-Host "Retrieving shared mailboxes..." -ForegroundColor Yellow
Write-Host ""

try {
    $SharedMailboxes = Get-Mailbox -RecipientTypeDetails SharedMailbox -ResultSize Unlimited | Sort-Object DisplayName

    if ($SharedMailboxes) {
        Write-Host "Found $($SharedMailboxes.Count) shared mailbox(es)" -ForegroundColor Green
        Write-Host ""

        foreach ($Mailbox in $SharedMailboxes) {
            Write-Host "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━" -ForegroundColor DarkGray
            Write-Host "Display Name: $($Mailbox.DisplayName)" -ForegroundColor Cyan
            Write-Host "Email: $($Mailbox.PrimarySmtpAddress)" -ForegroundColor Gray

            # Get mailbox size
            $Stats = Get-MailboxStatistics -Identity $Mailbox.PrimarySmtpAddress
            Write-Host "Size: $($Stats.TotalItemSize)" -ForegroundColor Gray
            Write-Host "Items: $($Stats.ItemCount)" -ForegroundColor Gray

            # Get users with access
            $Permissions = Get-MailboxPermission -Identity $Mailbox.PrimarySmtpAddress | Where-Object {$_.User -notlike "NT AUTHORITY\*" -and $_.User -notlike "S-1-5-*"}
            if ($Permissions) {
                Write-Host "Users with access:" -ForegroundColor Yellow
                foreach ($Perm in $Permissions) {
                    Write-Host "  - $($Perm.User): $($Perm.AccessRights -join ', ')" -ForegroundColor Gray
                }
            }
            Write-Host ""
        }

        Write-Host "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━" -ForegroundColor DarkGray
        Write-Host ""
        Write-Host "Total: $($SharedMailboxes.Count) shared mailbox(es)" -ForegroundColor Green

    } else {
        Write-Host "No shared mailboxes found" -ForegroundColor Yellow
    }

} catch {
    Write-Host "❌ Error retrieving shared mailboxes: $_" -ForegroundColor Red
}

# Block/Unblock M365 User Sign-In
# Generated: $(Get-Date)
# NOTE: Must be connected to Azure AD

$UserEmail = "{{user_email}}"
$Action = "{{action}}"

Write-Host "=== M365 USER SIGN-IN CONTROL ===" -ForegroundColor Cyan
Write-Host ""
Write-Host "User: $UserEmail" -ForegroundColor Yellow
Write-Host "Action: $Action" -ForegroundColor Yellow
Write-Host ""

try {
    if ($Action -eq "Block") {
        Set-AzureADUser -ObjectId $UserEmail -AccountEnabled $false
        Write-Host "✅ User sign-in BLOCKED successfully!" -ForegroundColor Red
        Write-Host ""
        Write-Host "The user will be signed out within 60 minutes" -ForegroundColor Yellow
        Write-Host "They cannot sign in until unblocked" -ForegroundColor Yellow
    } else {
        Set-AzureADUser -ObjectId $UserEmail -AccountEnabled $true
        Write-Host "✅ User sign-in UNBLOCKED successfully!" -ForegroundColor Green
        Write-Host ""
        Write-Host "The user can now sign in to Microsoft 365" -ForegroundColor Cyan
    }

} catch {
    Write-Host "❌ Error: $_" -ForegroundColor Red
}

# Export All Active Mailboxes to CSV
# Generated: $(Get-Date)
# NOTE: Must be connected to Exchange Online and Azure AD

$ExportPath = "{{export_path}}"
$MailboxType = "{{mailbox_type}}"

Write-Host "=== EXPORT M365 MAILBOXES ===" -ForegroundColor Cyan
Write-Host ""
Write-Host "Export Path: $ExportPath" -ForegroundColor Yellow
Write-Host "Mailbox Type: $MailboxType" -ForegroundColor Yellow
Write-Host ""

# Ensure export directory exists
$ExportDir = Split-Path $ExportPath -Parent
if (!(Test-Path $ExportDir)) {
    Write-Host "Creating directory: $ExportDir" -ForegroundColor Yellow
    New-Item -ItemType Directory -Path $ExportDir -Force | Out-Null
}

try {
    Write-Host "Retrieving mailboxes..." -ForegroundColor Cyan
    Write-Host "This may take several minutes for large organizations..." -ForegroundColor Gray
    Write-Host ""

    # Get mailboxes based on type
    if ($MailboxType -eq "All") {
        $Mailboxes = Get-Mailbox -ResultSize Unlimited | Sort-Object DisplayName
    } else {
        $Mailboxes = Get-Mailbox -RecipientTypeDetails $MailboxType -ResultSize Unlimited | Sort-Object DisplayName
    }

    if (!$Mailboxes) {
        Write-Host "No mailboxes found" -ForegroundColor Yellow
        exit
    }

    Write-Host "Found $($Mailboxes.Count) mailbox(es)" -ForegroundColor Green
    Write-Host "Processing mailbox details..." -ForegroundColor Cyan
    Write-Host ""

    $Results = @()
    $Counter = 0

    foreach ($Mailbox in $Mailboxes) {
        $Counter++
        Write-Progress -Activity "Processing Mailboxes" -Status "$Counter of $($Mailboxes.Count): $($Mailbox.DisplayName)" -PercentComplete (($Counter / $Mailboxes.Count) * 100)

        try {
            # Get mailbox statistics
            $Stats = Get-MailboxStatistics -Identity $Mailbox.PrimarySmtpAddress -ErrorAction SilentlyContinue

            # Get Azure AD user info for additional details
            $AzureUser = $null
            try {
                $AzureUser = Get-AzureADUser -ObjectId $Mailbox.PrimarySmtpAddress -ErrorAction SilentlyContinue
            } catch {}

            # Get licenses
            $Licenses = ""
            try {
                $LicenseDetails = Get-AzureADUserLicenseDetail -ObjectId $Mailbox.PrimarySmtpAddress -ErrorAction SilentlyContinue
                if ($LicenseDetails) {
                    $Licenses = ($LicenseDetails.SkuPartNumber -join "; ")
                }
            } catch {}

            # Create custom object with all info
            $MailboxInfo = [PSCustomObject]@{
                DisplayName = $Mailbox.DisplayName
                UserPrincipalName = $Mailbox.UserPrincipalName
                PrimarySmtpAddress = $Mailbox.PrimarySmtpAddress
                MailboxType = $Mailbox.RecipientTypeDetails
                AccountEnabled = if ($AzureUser) { $AzureUser.AccountEnabled } else { "N/A" }
                Department = if ($AzureUser) { $AzureUser.Department } else { "" }
                JobTitle = if ($AzureUser) { $AzureUser.JobTitle } else { "" }
                Office = if ($AzureUser) { $AzureUser.PhysicalDeliveryOfficeName } else { "" }
                City = if ($AzureUser) { $AzureUser.City } else { "" }
                Country = if ($AzureUser) { $AzureUser.Country } else { "" }
                MailboxSizeMB = if ($Stats) { [math]::Round(($Stats.TotalItemSize.ToString() -replace '.*\(([0-9,]+).*','$1' -replace ',','' ) / 1MB, 2) } else { 0 }
                MailboxSizeGB = if ($Stats) { [math]::Round(($Stats.TotalItemSize.ToString() -replace '.*\(([0-9,]+).*','$1' -replace ',','' ) / 1GB, 2) } else { 0 }
                ItemCount = if ($Stats) { $Stats.ItemCount } else { 0 }
                DeletedItemCount = if ($Stats) { $Stats.DeletedItemCount } else { 0 }
                LastLogonTime = if ($Stats) { $Stats.LastLogonTime } else { "Never" }
                LastUserActionTime = if ($Stats) { $Stats.LastUserActionTime } else { "Never" }
                Licenses = $Licenses
                ArchiveStatus = $Mailbox.ArchiveStatus
                LitigationHoldEnabled = $Mailbox.LitigationHoldEnabled
                WhenCreated = $Mailbox.WhenCreated
                EmailAddresses = ($Mailbox.EmailAddresses | Where-Object {$_ -like "smtp:*"}) -join "; "
            }

            $Results += $MailboxInfo

        } catch {
            Write-Host "  Warning: Error processing $($Mailbox.DisplayName): $_" -ForegroundColor Yellow
        }
    }

    Write-Progress -Activity "Processing Mailboxes" -Completed

    # Export to CSV
    Write-Host ""
    Write-Host "Exporting to CSV..." -ForegroundColor Cyan
    $Results | Export-Csv -Path $ExportPath -NoTypeInformation -Encoding UTF8

    Write-Host ""
    Write-Host "✅ EXPORT COMPLETE!" -ForegroundColor Green
    Write-Host ""
    Write-Host "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━" -ForegroundColor DarkGray
    Write-Host "Total Mailboxes: $($Results.Count)" -ForegroundColor Cyan
    Write-Host "Export File: $ExportPath" -ForegroundColor Cyan
    Write-Host "File Size: $([math]::Round((Get-Item $ExportPath).Length / 1KB, 2)) KB" -ForegroundColor Cyan
    Write-Host "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━" -ForegroundColor DarkGray
    Write-Host ""

    # Summary statistics
    $TotalSizeGB = ($Results | Measure-Object -Property MailboxSizeGB -Sum).Sum
    $TotalItems = ($Results | Measure-Object -Property ItemCount -Sum).Sum
    $ActiveUsers = ($Results | Where-Object {$_.LastLogonTime -ne "Never"}).Count

    Write-Host "Summary Statistics:" -ForegroundColor Yellow
    Write-Host "  Total Mailbox Size: $([math]::Round($TotalSizeGB, 2)) GB" -ForegroundColor Gray
    Write-Host "  Total Items: $TotalItems" -ForegroundColor Gray
    Write-Host "  Active Users (logged in): $ActiveUsers" -ForegroundColor Gray
    Write-Host "  Inactive Users: $($Results.Count - $ActiveUsers)" -ForegroundColor Gray

    if ($Results.Count -gt 0) {
        $AvgSizeGB = [math]::Round($TotalSizeGB / $Results.Count, 2)
        Write-Host "  Average Mailbox Size: $AvgSizeGB GB" -ForegroundColor Gray
    }

    Write-Host ""
    Write-Host "[TIP] Open the CSV file in Excel for detailed analysis" -ForegroundColor Cyan

} catch {
    Write-Host "❌ Error during export: $_" -ForegroundColor Red
}
